      "source_scopes": [
        {
          "sid": "s001",
          "scope_zh": "使某对象处于并继续保持某种状态、位置或活动（如保持清洁、保持原位）",
          "recommended_pos": "动词",
          "required_context": "宾语为状态补语或表示状态/位置/活动的名词短语",
          "evidence_ids": ["wn31:v:02687605"],
          "uncertainty": "证据为及物动词，含使役含义，与原文匹配；但原文未限定对象类型，证据中示例含清洁、位置等，范围可能较宽，未发现非使役独立证据。"
        },
        {
          "sid": "s002",
          "scope_zh": "保持（某状态、数量、记录等，一般及物）",
          "recommended_pos": "动词",
          "required_context": "需要宾语，宾语可为状态/数量/记录等",
          "evidence_ids": ["wn31:v:02687605"],
          "uncertainty": "与s001高度重叠，可能为同义重复；中文‘保持’比‘使保持某状态’少显性使役，但英语证据已包含使役，未发现非使役独立证据。"
        },
        {
          "sid": "s003",
          "scope_zh": "维持（某状态、活动等，常含持续努力）",
          "recommended_pos": "动词",
          "required_context": "需要宾语，宾语可为状态/活动/机构等",
          "evidence_ids": ["wn31:v:02687605"],
          "uncertainty": "与s001/s002类似，但英语证据未区分‘维持’所需的持续投入，可能过于笼统。"
        }
      ],
      "proposed_core": [
        "动词：使保持某状态；保持；维持（使某对象继续处于某种状态、位置或活动）"
      ],
      "deferred_source_ids": [],
      "deferral_reason": "",
      "note": "三个源义项高度同义，均映射至同一个使役性状态保持证据。其他字典义（如声称、供给、记录、持有、保护等）未在源中出现，不加为核心。",
